from assemble_topic import assemble, W, read, dump, stamp
FACTS={
'01':('Map interpretation combines title, key, valid scale and orientation rather than symbols or page position alone.','A schematic training map does not establish unprovided real-place facts or current service outcomes.'),
'01-01':('A title identifies place, topic or extent while dates need checking against the observation record.','Different map purposes select different information from the same area.'),
'01-02':('The supplied key defines symbols and colour meanings.','A symbol can locate a facility without giving its capacity, condition or exact scaled dimensions.'),
'01-03':('At 1:50,000, one centimetre at intended size represents 500 metres on the ground.','Resizing changes physical ruler measurements, while a consistently resized scale bar retains its proportional use.'),
'01-04':('Direction follows the stated north reference rather than an arbitrary screen top.','Grid, true and magnetic north are distinct and corrections cannot be imported without appropriate place/date evidence.'),
'02':('Distance is linear, area uses two dimensions and gradient compares vertical change with horizontal run in like units.','The requested endpoints, path and measurement definition determine which calculation is appropriate.'),
'02-01':('Four centimetres at 1:50,000 represents two kilometres, while six represents three.','Curved route length differs from straight separation and requires following the specified path.'),
'02-02':('A one-centimetre square at 1:50,000 represents 0.25 square kilometres.','A two-kilometre square has area four square kilometres, not two.'),
'02-03':('Forty metres rise over 2,000 metres horizontal run simplifies to gradient 1:50.','A smaller denominator in 1:n indicates a steeper slope, with the result an endpoint average rather than proof of uniform slope.'),
'03':('A local bearing is measured clockwise from the stated north at the starting point and written in three-figure degree form.','A reverse bearing differs by 180 degrees in the local planar exercises.'),
'03-01':('Equal positive east and north offsets give the north-east direction in the supplied perpendicular grid.','A direction alone does not establish distance or a usable route.'),
'03-02':('Due east has bearing 090 degrees and its reverse due west 270 degrees under the same north reference.','A protractor must be centred at the origin rather than the destination or the printed north-arrow position.'),
'04':('Contours connect equal elevations and labelled interval/spacing support landform interpretation.','A supplied cross-section can be interpreted without constructing a new one, with scale exaggeration considered.'),
'04-01':('Inward-rising closed contours with a higher spot height support a hill interpretation.','Valley contour bends, watercourse and height sequence must be read together rather than drainage substituted for relief.'),
'04-02':('Landform and surface symbols follow the supplied key rather than a remembered colour convention.','A symbol’s presence does not establish every current seasonal condition or usable resource quantity.'),
'05':('Mapped activity suggestions need visible or keyed evidence and appropriate conditions.','A service category and the facility supplying it are related but distinct fields.'),
'06':('Horizontal and oblique photographs offer different views and perspective limits for visible features.','Actual photographic interpretation requires the selected image rather than a written replacement or unverified imagined scene.'),
'06-01':('Horizontal views can show foreground/middle/background with occlusion and varying apparent scale.','Visible form can support a simple description without proving precise measurement, climate or household welfare.'),
'06-02':('Oblique views can reveal spatial relationships while perspective still distorts scale.','An apparent land use needs visible support, and outside-frame conditions or exact causes remain unverified.'),
'07':('Latitude measures north/south angular position and longitude east/west position with hemisphere or clear signed convention.','Latitude/longitude and projected linear grids are different coordinate systems that must be represented consistently.'),
'07-01':('Larger south-latitude magnitude lies farther south while smaller south magnitude lies nearer the Equator.','One minute of latitude is an angular difference, not a supplied map-scale length.'),
'07-02':('Increasing east-longitude magnitude is eastward under the stated eastern-hemisphere exercise.','Longitude ground spacing varies with latitude, so equal angular longitude and latitude differences need not be equal distances.'),
'07-03':('One degree has sixty minutes and one minute sixty seconds.','DMS-to-decimal conversion uses degrees plus minutes/60 plus seconds/3600 rather than decimal concatenation.')}
CARDS={
'001':('Name the map element explaining symbols and colours.','The key or legend.',['1 mark for the element name key/legend.']),
'002':('Describe what the supplied training map’s title, full key, 1:50,000 scale and grid-north arrow each help establish.','The title identifies the represented area/purpose; the key decodes features; scale and north support distance and direction. Those elements do not establish current service reliability or unprovided place facts.',['1 mark for the map-information relationship; 1 for relevant title/key/scale evidence; 1 for the interpretation limit.']),
'003':('Name the element identifying the map’s place or topic.','The title.',['1 mark for the element name title.']),
'004':('Name the element to check before interpreting a coloured land-use symbol.','The map key or legend.',['1 mark for the element name key/legend.']),
'005':('Name the ground distance represented by one centimetre on an intended-size 1:50,000 map.','500 metres or 0.5 kilometre.',['1 mark for the correct scaled-distance point with unit.']),
'006':('Name the direction reference to use for bearings when the supplied arrow is explicitly grid north.','Grid north.',['1 mark for the reference name grid north.']),
'007':('Calculate the ground distance of a six-centimetre straight line on a valid intended-size 1:50,000 map.','6×500 = 3,000 metres, equivalent to three kilometres.',['1 mark for the scale-multiplication method; 1 for the correct answer three; 1 for the kilometre unit or equivalent metres.']),
'008':('Describe the supplied map geometry: A–B measures four centimetres directly, while its road route measures six at the same valid 1:50,000 scale.','Straight separation is two kilometres and road distance three. The route is longer because it follows a different path. The record does not establish travel time or service frequency.',['1 mark for the direct/route pattern; 1 for scaled-value evidence; 1 for the access/time limitation.']),
'009':('Calculate straight A–B ground distance when the valid 1:50,000 map line is four centimetres.','4×500 = 2,000 metres, or two kilometres.',['1 mark for the scale method; 1 for the correct answer two; 1 for the kilometre unit or equivalent metres.']),
'010':('Describe the distance implication when a curved route is six centimetres but its chord is four centimetres on the same 1:50,000 map.','The route corresponds to three kilometres while direct separation is two. Measuring the chord would not answer the route-length question. The difference concerns path, not a changed scale.',['1 mark for the path-length relationship; 1 for scaled evidence; 1 for the measure distinction.']),
'011':('Calculate ground area of the A–B–C–D square with side four centimetres on a valid 1:50,000 map.','Each side represents two kilometres; the area is 2×2 = 4 square kilometres.',['1 mark for the method of converting the linear dimensions before area; 1 for the correct answer four; 1 for the square-kilometre unit.']),
'012':('Describe the area relationship for a one-centimetre square on a 1:50,000 map.','Its sides each represent half a kilometre and its ground area is 0.25 km². Area conversion uses two dimensions, not the linear half-kilometre factor alone.',['1 mark for the two-dimension pattern; 1 for the side/area evidence; 1 for the linear-versus-area distinction.']),
'013':('Calculate average A–B gradient: elevations A 1,500 m and B 1,540 m; horizontal ground distance two kilometres. Express 1:n.','Rise is forty metres and run 2,000 metres. The ratio 40:2,000 simplifies to 1:50.',['1 mark for height-difference and same-unit method; 1 for the correct simplified answer; 1 for the dimensionless rise:horizontal-run ratio convention.']),
'014':('Describe the slope comparison between average gradients 1:20 and 1:50, with local shape otherwise unmeasured.','The 1:20 average is steeper: the same unit rise occurs over a shorter horizontal run. The ratios do not establish uniform slope at every point or which line has greater absolute elevation.',['1 mark for the comparative steepness pattern; 1 for ratio evidence; 1 for the average/elevation limit.']),
'015':('Calculate A→C bearing on the supplied perpendicular grid when C lies equally far east and north of A, using grid north.','The line bisects the north/east right angle, giving 045° clockwise from grid north.',['1 mark for the equal-offset/right-angle method; 1 for answer 45; 1 for the degree unit and three-figure notation 045°.']),
'016':('Describe the supplied direction panel: A→B east, A→D north and A→C equal east/north offsets.','A→B is 090°, A→D 000° and A→C 045° from the shown grid north. These are relative straight-line directions, not evidence of a safe road between every point.',['1 mark for the relative-direction pattern; 1 for bearing/grid evidence; 1 for the route limitation.']),
'017':('Calculate the clockwise angle from north for due east on the supplied compass circle, writing three figures.','East is a quarter of a full turn: 360/4 = 90 degrees, written 090°.',['1 mark for the quarter-turn method; 1 for answer 90; 1 for the degree unit and three-figure form.']),
'018':('Describe the compass position when B has a larger easting than A but the same northing on the supplied perpendicular grid.','B lies east of A. The unchanged north coordinate means no north–south offset. The position does not by itself establish distance or a usable journey.',['1 mark for the eastward relationship; 1 for coordinate evidence; 1 for the separation/access limit.']),
'019':('Calculate the reverse local bearing B→A when A→B is 090°, using the same north reference.','Add 180 degrees to ninety, giving 270°.',['1 mark for the reverse-bearing method; 1 for answer 270; 1 for the degree unit and three-figure convention.']),
'020':('Describe the bearing check if a destination visibly lies north-east on a grid-north map but a reading gives 225°.','225° points south-west, the opposite quadrant. The start, reference or protractor reading needs checking. The given image direction and calculated result cannot both describe the same A→destination line.',['1 mark for the quadrant mismatch pattern; 1 for direction/value evidence; 1 for the relevant checking interpretation.']),
'021':('Name the landform supported by closed contours increasing inward to a higher spot height.','A hill.',['1 mark for the landform name hill.']),
'022':('Describe the supplied relief panel: closed contours 1,510,1,520,1,530 m surround a 1,540 m spot height, with equal stated intervals.','Elevation rises inward, supporting a hill. Spacing can show variations in slope under the common interval. The pattern does not establish vegetation or household activity without keyed evidence.',['1 mark for the inward-rise pattern; 1 for contour/height evidence; 1 for the non-relief limitation.']),
'023':('Name lines joining points of equal elevation on a map.','Contours.',['1 mark for the line name contours.']),
'024':('Name the map element to check before interpreting a cliff or marsh symbol.','The supplied key.',['1 mark for the element name key.']),
'025':('Name the service supplied by a mapped clinic building.','Healthcare or medical services.',['1 mark for the service name healthcare.']),
'026':('Describe the mapped human-use relationships: school at D, clinic at C, a road joining relevant points and cultivation separately keyed; transport frequency is absent.','The key identifies facilities and land use, and the road shows a connection. Education and healthcare are the corresponding services. The map does not establish capacity, opening hours or affordable frequent transport.',['1 mark for the facility/use pattern; 1 for key/network evidence; 1 for the service-operation limitation.']),
'027':('Describe three visible physical features in the supplied horizontal coastal photograph, using their positions in the image.','Provisional scene-matched answer: beach material in the foreground, sea beside it and a cliff rising behind the beach. These features must be verified or rewritten against the actual licensed photograph before this card is usable.',['1 mark for each of three accurate visible-feature/position observations supported by photographic evidence; no credit for invented causes or outside-frame features.']),
'028':('Suggest one land use supported by the supplied oblique photograph of field plots and nearby access, giving visible evidence and one limit.','Provisional scene-matched answer: agriculture is supported by visible bounded cultivated plots; the image does not establish exact crop, irrigation or commercial purpose unless further visible/caption evidence supplies it. Verify against the selected photograph before use.',['1 mark for a suitable given-image suggestion; 1 for a genuinely visible plot-use reason; 1 for a relevant evidence limit/application.']),
'029':('Describe three visible features of the valley in the supplied horizontal photograph, using foreground, middle distance or background.','Provisional scene-matched answer: a channel in the foreground, valley sides in the middle distance and rising ground behind. Actual positions and features must be reconciled to the licensed image rather than assumed from this provisional scene requirement.',['1 mark for each accurate visible feature and its image-position relationship, supported by evidence in the actual photograph.']),
'030':('Suggest a cautious environmental interpretation of the supplied horizontal photograph’s vegetation, with a visible reason and a limitation.','Provisional scene-matched answer: scattered shrubs and exposed ground can be consistent with water-limited vegetation. One photograph does not establish annual rainfall or exclude seasonal/disturbance effects. Verify the actual visible cover before retaining this answer.',['1 mark for a suitable given-image suggestion; 1 for the visible-cover reason; 1 for the climate/seasonality limitation.']),
'031':('Describe the settlement arrangement and route relationship visible in the supplied oblique photograph, keeping the conclusion within its frame.','Provisional scene-matched answer: buildings cluster near a route junction, with less built land around the visible cluster. This supports a local nucleated arrangement, not the pattern of a whole region. The selected image must actually show these relationships or the answer must be revised.',['1 mark for the accurate visible settlement pattern; 1 for supporting route/spacing evidence; 1 for the frame/extent limit.']),
'032':('Suggest how visible relief may relate to the route in the supplied oblique valley photograph, giving a visible reason and a limit.','Provisional scene-matched answer: a route on gentler valley-floor ground may avoid steeper sides visible nearby. The image alone does not establish engineering cost, exact gradient or the complete historical reason. Retain only if the actual licensed image supports those features.',['1 mark for a suitable given-image suggestion; 1 for the visible relief/access reason; 1 for the measurement/causal limit.']),
'033':('Calculate the local angular midpoint between P 23°00′30″S,17°00′30″E and Q 23°01′30″S,17°01′30″E.','Each coordinate changes one minute, so halfway adds thirty seconds to P: 23°01′00″S,17°01′00″E.',['1 mark for the halfway-angular-difference method; 1 for the correct paired-coordinate answer; 1 for DMS units/hemispheres and latitude-first form.']),
'034':('Describe the supplied coordinate panel: P 23°00′30″S,17°00′30″E and Q 23°01′30″S,17°01′30″E.','Q lies farther south and east in angular position. Each coordinate differs by one minute. Equal angular differences do not establish equal ground lengths or a ruler distance without the appropriate map scale/projection.',['1 mark for the south/east pattern; 1 for DMS evidence; 1 for the angular/linear limitation.']),
'035':('Calculate the angular latitude difference from 23°00′30″S to 23°01′30″S, including direction.','The difference is one minute of latitude towards the south.',['1 mark for the method of subtracting compatible angular values; 1 for answer one; 1 for minute-of-latitude unit and southward direction.']),
'036':('Describe the north–south relationship of 23°00′30″S and 23°01′30″S.','The smaller south magnitude is farther north, so the first lies north of the second. The difference concerns latitude, not longitude or an automatically known road distance.',['1 mark for the directional relationship; 1 for latitude-value evidence; 1 for the coordinate/route distinction.']),
'037':('Calculate the angular longitude difference from 17°00′30″E to 17°01′30″E, including direction.','The difference is one minute of longitude towards the east.',['1 mark for the compatible angular subtraction method; 1 for answer one; 1 for minute-of-longitude unit and eastward direction.']),
'038':('Describe the east–west relationship of 17°00′30″E and 17°01′30″E at the stated locality.','The larger east magnitude is farther east. The second is one minute east of the first. The angular difference alone does not establish a fixed kilometre distance independent of latitude and projection.',['1 mark for the eastward relationship; 1 for longitude evidence; 1 for the angular/ground-distance limit.']),
'039':('Calculate decimal-degree latitude for 23°01′30″S, retaining a clear hemisphere convention.','23 + 1/60 + 30/3600 = 23.025 degrees south, or −23.025° in a stated signed convention.',['1 mark for the DMS-to-decimal method; 1 for answer 23.025; 1 for degree unit and south/negative convention without mixing them ambiguously.']),
'040':('Describe the angular-unit correction to a record that treats 23°01′30″ as 23.0130 decimal degrees.','Minutes and seconds use base sixty rather than decimal concatenation. The correct magnitude is 23.025 degrees, because one minute and thirty seconds equal 0.025 degrees. Hemisphere still needs recording.',['1 mark for the base-sixty/decimal pattern; 1 for conversion evidence; 1 for the hemisphere/format condition.']),
'041':('Explain the error in writing “school” in both the building and service fields of a map answer. What distinction tests the pair?','The confusion repeats a facility instead of naming its service. The building is a school and the service education. Check whether one field identifies the mapped facility and the other what it supplies.',['1 mark for the facility/service confusion; 1 for the correct distinction and paired-field test.'])}
TASKS=[{'objectives':['01','02','03','05'],'prompt':'Use the supplied original 1:50,000 training map with full key and grid-north arrow. A is at local metre position (2000,2000), B (4000,2000), C (4000,4000), D (2000,4000); x east/y north. A and B have spot heights 1,500 and 1,540 m. School is keyed at D and clinic at C. The map’s straight A–B length is four centimetres at intended size.\n(a) Name the service supplied by the clinic. [1]\n(b) Calculate straight A–B ground distance from the scale. [2]\n(c) Describe three distinct mapped relationships involving position, area or relief. [3]\n(d) What judgement is supported about the claim “the road symbol proves frequent affordable public transport”? [1]','answer':'(a) Healthcare. (b) Four centimetres at 500 metres per centimetre gives 2,000 metres or two kilometres. (c) B is east of A; C/D lie north of B/A respectively; the ABCD square has four km² area; B is forty metres higher than A. Credit three distinct map-supported relationships. (d) Reject the service-frequency claim: a road locates a connection, while operation and affordability are not supplied.','guide':['(a) 1 A mark for healthcare.','(b) 2 B marks for the scale method and correct distance/unit.','(c) 3 B marks for distinct resource-based spatial/area/relief patterns with supporting map evidence.','(d) 1 C mark for a supported mapped-connection/service judgement.'],'split':{'A':1,'B':5,'C':1},'parts':[('a','Name',1,'A'),('b','Calculate',2,'B'),('c','Describe',3,'B'),('d','What',1,'C')],'assets_required':['VIS-6137-4.2-01 full-key base map reuse','VIS-6137-4.2-02 measurement/height variant reuse']}]
SOURCES=[('ORDNANCE-SURVEY-MAP-SKILLS','https://www.ordnancesurvey.co.uk/documents/resources/map-reading.pdf'),('ORDNANCE-SURVEY-BEARINGS','https://www.ordnancesurvey.co.uk/mapzone/map-skills/compass-bearings/page-three'),('NGA-COORDINATE-SYSTEMS','https://earth-info.nga.mil/?action=coordsys&dir=coordsys'),('USGS-TOPOVIEW','https://ngmdb.usgs.gov/topoview/help/'),('RGS-PHOTOGRAPHY','https://www.rgs.org/schools/resources-for-schools/sketching-and-photography/')]
if __name__=='__main__':
 assemble('4.2',FACTS,CARDS,TASKS,SOURCES)
 td=W/'topics/4.2';wo=read(td/'work_order.json');p=td/wo['output_files']['learning_items'];d=read(p);reuses=[];photo=[]
 for i in d['items']:
  num=i['item_id'].split('-')[-2]
  r='VIS-6137-4.2-02' if num in ['007','009','010','011','012','013','014'] else 'VIS-6137-4.2-03' if num in ['015','017','018','019','020','022'] else 'VIS-6137-4.2-04' if num in ['033','035','036','037','038','039','040'] else 'VIS-6137-4.2-01' if num=='026' else None
  if r:
   i['context']['situation']='VISUAL PENDING: map-panel reuse of '+r+'; exact scale, key, geometry and reference stated in prompt. Claude authoring and Codex review pending.';stamp(i,i['claim_ids']);reuses.append({'item_id':i['item_id'],'resource_id':r})
  if num in ['027','028','029','030','031','032']:
   i['context']['situation']='PROVISIONAL PHOTO ANSWER: no photograph selected or inspected. Assigned resource '+next(v['resource_id'] for v in read(W/'planning/visual-resource-plan-6137.json')['resources'] if v['assigned_item_id']==i['item_id'])+'; Claude must source a permitted actual photo, then match or revise prompt/answer/rubric after viewing it. Codex must independently inspect the actual asset. This is a filled draft slot, not a verified visual answer.';stamp(i,i['claim_ids']);photo.append(i['item_id'])
 dump(p,d);n=read(td/'authoring_notes.json');n['visual_reuses']=reuses;n['provisional_photo_answers']=photo;n['photo_gate']='These six canonical answers are provisional scene requirements, not claims about unseen images. No learner publication until actual licensed photographs are selected, all text is reconciled against them and Codex accepts the assets.';n['map_geometry']={'scale':'1:50000 at declared physical output size; use valid scale bars for resized viewing','local_grid':'x east/y grid north in metres','points':{'A':[2000,2000],'B':[4000,2000],'C':[4000,4000],'D':[2000,4000]},'heights_m':{'A':1500,'B':1540},'key_requirements':['school at D','clinic at C','separately keyed cultivation, water and routes','north reference and contour interval'],'coordinate_panel':{'P':['23°00′30″S','17°00′30″E'],'Q':['23°01′30″S','17°01′30″E'],'requirement':'Generate consistent projected geometry/graticule in software; do not assign arbitrary degree labels to a linear grid. A coordinate-panel variant may use its own extent but retains 1:50000 and full orientation/key.'},'terrain_requirement':'All contour/spot-height assertions must come from one internally consistent generated terrain per panel; no tracing of official inserts.'};dump(td/'authoring_notes.json',n)
